from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path
import pandas as pd
from run_multi_model_small_eval import extract_sva_candidates

def sha(p: Path): return hashlib.sha256(p.read_bytes()).hexdigest()
def truth(s): return s.astype(str).str.lower().isin(["true","1"])

def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--direct-dir",required=True); ap.add_argument("--two-stage-dir",required=True); ap.add_argument("--cases-root",required=True); ap.add_argument("--out-dir",required=True); a=ap.parse_args()
