    qwen_comparison=pd.concat([direct_q,q2],ignore_index=True); qwen_comparison.to_csv(out/"qwen_two_stage_comparison.csv",index=False,encoding="utf-8-sig")
    q2_cost={c:pd.NA for c in cost.columns}; q2_cost.update({"model_label":"Qwen","model_name":qt.model_name.iloc[0],"baseline":"property_then_sva","case_count":qt.case_id.nunique(),"candidate_budget_per_cell":len(qt)//qt.case_id.nunique(),"candidate_count":len(qt),"compile_rate":qt.compile_ok.mean(),"visible_success_rate":qt.visible_success.mean(),"heldout_success_rate":qt.heldout_success.mean(),"successful_parent_count":q2_success_parents,"duplicate_candidate_rate":float(q2_canon.duplicated().mean()),"prompt_tokens":pd.to_numeric(qt.prompt_tokens).sum(),"output_tokens":pd.to_numeric(qt.output_tokens).sum(),"total_tokens":q2_total_tokens,"generation_duration_sec":pd.to_numeric(qt.generation_duration_sec).sum(),"compile_duration_sec":pd.to_numeric(qt.compile_duration_sec).sum(),"verification_duration_sec":pd.to_numeric(qt.verification_duration_sec).sum(),"tokens_per_new_success_parent":q2_total_tokens/q2_success_parents if q2_success_parents else pd.NA,"seconds_per_new_success_parent":q2_total_seconds/q2_success_parents if q2_success_parents else pd.NA,"usd_cost_status":"unavailable_on_public_price_page"}); cost.insert(2,"baseline","direct_sva"); q2_cost={c:q2_cost.get(c,pd.NA) for c in cost.columns}; cost=pd.concat([cost,pd.DataFrame([q2_cost])],ignore_index=True); cost.to_csv(out/"cost_table.csv",index=False,encoding="utf-8-sig")
