    for cache_key,item in sorted(two_cache.items()):
        ir_prompt=str(item["ir_prompt"]); prompt_seal[f"qwen_two_stage/{cache_key}/stage1_ir"] = hashlib.sha256(ir_prompt.encode()).hexdigest(); two_stage_ir_count+=1
